import { TransitionSeries, linearTiming } from "@remotion/transitions";
import { fade } from "@remotion/transitions/fade";

export const fps = 25;

// Total duration matching script: ~1:03:24 = ~1584 frames
// Scene durations (no transitions subtracted yet)
const S1 = 55;   // 0:00-0:02:04 chaos
const S2 = 125;  // 0:02:04-0:07:10 only a fraction
const S3 = 55;   // 0:07:10-0:09:13 drive reach
const S4 = 105;  // 0:09:13-0:13:14 can't see post counts
const S5 = 98;   // 0:13:19-0:17:12 search one by one
const S6 = 118;  // 0:17:24-0:22:11 teams guessing
const S7 = 123;  // 0:22:17-0:27:10 vague tools
const S8 = 73;   // 0:28:01-0:30:10 right vs wrong
const S9 = 75;   // 0:30:10-0:33:10 buried vs discovered
const S10 = 87;  // 0:33:11-0:36:23 not just social media
const S11 = 68;  // 0:36:23-0:39:11 campaign launch
const S12 = 72;  // 0:39:11-0:42:09 where research begins
const S13 = 73;  // 0:42:09-0:45:02 mapping a market
const S14 = 83;  // 0:45:02-0:48:09 AI workflow
const S15 = 63;  // 0:48:15-0:51:03 start with hashtags
const S16 = 95;  // 0:51:03-0:54:20 wrong hashtag
const S17 = 102; // 0:55:04-0:58:20 right one unlocks
