const Scene2Fraction: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const allHashtags = Array.from({ length: 40 }, (_, i) => i);
  const activeIndices = new Set([2, 7, 12, 15, 22, 28, 33]);

  const titleProgress = spring({ frame, fps, delay: 5, config: { damping: 200 } });
  const filterProgress = spring({ frame, fps, delay: 40, config: { damping: 200 } });

  // Phase: show all hashtags first, then filter
  const phase2Start = 55;
  const filterOpacity = interpolate(frame, [phase2Start, phase2Start + 20], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill style={{ fontFamily: "'Inter', sans-serif" }}>
      <Background />
      <AbsoluteFill
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          paddingBottom: 200,
          gap: 60,
        }}
      >
        {/* Grid of hashtag dots */}
        <div style={{
          display: "grid",
          gridTemplateColumns: "repeat(8, 1fr)",
          gap: 28,
          opacity: interpolate(titleProgress, [0, 1], [0, 1]),
          transform: `translateY(${interpolate(titleProgress, [0, 1], [40, 0])}px)`,
        }}>
          {allHashtags.map((idx) => {
            const isActive = activeIndices.has(idx);
            const dotProg = spring({ frame, fps, delay: idx * 1.2, config: { damping: 200 } });
            const shouldFade = frame > phase2Start && !isActive;

            return (
              <div
                key={idx}
                style={{
                  width: 120,
                  height: 120,
                  borderRadius: "50%",
                  backgroundColor: isActive ? COLORS.pink : "rgba(255,255,255,0.15)",
                  border: isActive ? `3px solid ${COLORS.pink}` : "3px solid rgba(255,255,255,0.1)",
                  opacity: shouldFade
                    ? interpolate(frame, [phase2Start, phase2Start + 25], [0.6, 0.08], { extrapolateLeft: "clamp", extrapolateRight: "clamp" }) * dotProg
                    : dotProg,
                  transform: `scale(${interpolate(dotProg, [0, 1], [0, isActive ? 1.1 : 1])})`,
                  boxShadow: isActive ? `0 0 30px ${COLORS.pink}66` : "none",
                  transition: "all 0.3s ease",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                }}
              >
                {isActive && (
                  <svg width="50" height="50" viewBox="0 0 24 24" fill="none">
                    <path d="M7 17L17 7M17 7H7M17 7V17" stroke="white" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" />
                  </svg>
                )}
              </div>
            );
          })}
        </div>

        {/* Fraction label */}
        <div style={{
          opacity: filterOpacity * interpolate(filterProgress, [0, 1], [0, 1]),
          transform: `translateY(${interpolate(filterProgress, [0, 1], [30, 0])}px)`,
          textAlign: "center",
        }}>
          <div style={{
            fontSize: 100,
            fontWeight: 900,
            color: COLORS.pink,
            letterSpacing: "-0.03em",
            textShadow: `0 0 60px ${COLORS.pink}66`,
          }}>
            {Math.round(interpolate(filterProgress, [0, 1], [0, 7]))} / 40
          </div>
          <div style={{
            fontSize: 44,
            fontWeight: 600,
            color: "rgba(255,255,255,0.6)",
            marginTop: 12,
            letterSpacing: "0.05em",
          }}>
            actually used
          </div>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

