// SCENE 3: Drive Reach (0:07:10-0:09:13) - 55 frames
// ============================================================
const Scene3Reach: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const centerProg = spring({ frame, fps, delay: 3, config: { damping: 200 } });

  const rings = [
    { radius: 160, count: 6, delay: 10, color: COLORS.pink },
    { radius: 320, count: 10, delay: 20, color: COLORS.purple },
    { radius: 480, count: 14, delay: 30, color: COLORS.cyan },
  ];

  return (
    <AbsoluteFill style={{ fontFamily: "'Inter', sans-serif" }}>
      <Background />
      <AbsoluteFill style={{ display: "flex", alignItems: "center", justifyContent: "center" }}>
        {/* Ripple rings */}
        {[1, 2, 3].map((ring) => {
          const rippleProgress = interpolate(
            frame,
            [ring * 6, ring * 6 + 40],
            [0, 1],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );
          return (
            <div
              key={ring}
              style={{
                position: "absolute",
                width: ring * 340,
                height: ring * 340,
                borderRadius: "50%",
                border: `3px solid ${COLORS.pink}`,
                opacity: interpolate(rippleProgress, [0, 0.3, 1], [0, 0.6, 0]),
                transform: `scale(${interpolate(rippleProgress, [0, 1], [0.4, 1.4])})`,
              }}
            />
          );
        })}

        {/* Orbit dots */}
        {rings.map((ring, ri) => {
          const orbitProg = spring({ frame, fps, delay: ring.delay, config: { damping: 200 } });
          return Array.from({ length: ring.count }, (_, di) => {
            const angle = (di / ring.count) * Math.PI * 2 + frame * 0.015 * (ri % 2 === 0 ? 1 : -1);
            const x = Math.cos(angle) * ring.radius * orbitProg;
            const y = Math.sin(angle) * ring.radius * orbitProg;
            return (
              <div
                key={`${ri}-${di}`}
                style={{
                  position: "absolute",
                  width: 22 - ri * 3,
                  height: 22 - ri * 3,
                  borderRadius: "50%",
                  backgroundColor: ring.color,
                  transform: `translate(${x}px, ${y}px)`,
                  opacity: orbitProg * 0.85,
                  boxShadow: `0 0 15px ${ring.color}88`,
                }}
              />
            );
          });
        })}

        {/* Center icon */}
        <div style={{
          width: 180,
          height: 180,
          borderRadius: "50%",
          backgroundColor: COLORS.pink,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          opacity: centerProg,
          transform: `scale(${interpolate(centerProg, [0, 1], [0, 1])})`,
          boxShadow: `0 0 80px ${COLORS.pink}88`,
          zIndex: 10,
        }}>
          <svg width="90" height="90" viewBox="0 0 24 24" fill="none">
            <path d="M13 10V3L4 14h7v7l9-11h-7z" fill="white" />
          </svg>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

