// SCENE 5: Search One by One (0:13:19-0:17:12) - 98 frames
// ============================================================
const SEARCH_TERMS = ["#yoga", "#pilates", "#crossfit", "#hiit", "#cardio"];

const Scene5OneByOne: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const activeSearch = Math.min(Math.floor(frame / 18), SEARCH_TERMS.length - 1);
  const searchProg = spring({ frame: frame - activeSearch * 18, fps, config: { damping: 200 } });

  return (
    <AbsoluteFill style={{ fontFamily: "'Inter', sans-serif" }}>
      <Background />
      <AbsoluteFill
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          paddingBottom: 200,
          gap: 36,
        }}
      >
        {/* Stacked search bars - one by one */}
        {SEARCH_TERMS.map((term, i) => {
          const isVisible = i <= activeSearch;
          const isCurrent = i === activeSearch;
          const itemProg = spring({ frame: Math.max(0, frame - i * 18), fps, config: { damping: 200 } });

          if (!isVisible) return null;

          return (
            <div
              key={i}
              style={{
                width: 1400,
                backgroundColor: isCurrent ? "rgba(255,100,184,0.08)" : "rgba(255,255,255,0.04)",
                borderRadius: 24,
                border: `2px solid ${isCurrent ? COLORS.pink + "66" : "rgba(255,255,255,0.07)"}`,
                padding: "32px 48px",
                display: "flex",
                alignItems: "center",
                justifyContent: "space-between",
                opacity: interpolate(itemProg, [0, 1], [0, 1]),
                transform: `translateY(${interpolate(itemProg, [0, 1], [30, 0])}px)`,
              }}
            >
              <div style={{ display: "flex", alignItems: "center", gap: 28 }}>
                <svg width="44" height="44" viewBox="0 0 24 24" fill="none">
                  <circle cx="11" cy="11" r="8" stroke={isCurrent ? COLORS.pink : "rgba(255,255,255,0.3)"} strokeWidth="2.5" />
                  <path d="M21 21l-4.35-4.35" stroke={isCurrent ? COLORS.pink : "rgba(255,255,255,0.3)"} strokeWidth="2.5" strokeLinecap="round" />
                </svg>
                <span style={{
                  fontSize: 48,
                  fontWeight: 700,
                  color: isCurrent ? COLORS.pink : "rgba(255,255,255,0.5)",
                }}>
                  {term}
                </span>
              </div>
              {!isCurrent && (
                <svg width="40" height="40" viewBox="0 0 24 24" fill="none">
                  <path d="M20 6L9 17l-5-5" stroke="rgba(255,255,255,0.25)" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" />
                </svg>
              )}
              {isCurrent && (
                <div style={{
                  width: 16,
                  height: 16,
                  borderRadius: "50%",
                  backgroundColor: COLORS.pink,
                  animation: "pulse 1s infinite",
                  boxShadow: `0 0 20px ${COLORS.pink}`,
                  opacity: Math.sin(frame * 0.2) * 0.5 + 0.5,
                }} />
              )}
            </div>
          );
        })}

        {/* Counter */}
        <div style={{
          marginTop: 20,
          fontSize: 38,
          color: "rgba(255,255,255,0.35)",
          fontWeight: 500,
          letterSpacing: "0.05em",
          opacity: interpolate(frame, [30, 50], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" }),
        }}>
          {activeSearch + 1} / ∞ searched
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

